[InitializeOnLoad]public static class GridShiftV5Checks {
 static GridShiftV5Checks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("V5",false)){SessionState.SetBool("V5",false);new GameObject("Experience5Checks").AddComponent<GridShiftV5PlayChecks>();}};}
 public static void Batch(){EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");foreach(var w in Object.FindObjectsByType<ClimaReal>(FindObjectsSortMode.None))w.enabled=false;SessionState.SetBool("V5",true);EditorApplication.isPlaying=true;}
 public static void OfficeBatch(){EditorSceneManager.OpenScene("Assets/Scenes/Office.unity");foreach(var w in Object.FindObjectsByType<ClimaReal>(FindObjectsSortMode.None))w.enabled=false;SessionState.SetBool("V5",true);EditorApplication.isPlaying=true;}
 public static void Structure(){var report=new StringBuilder();try{foreach(string scene in new[]{"SampleScene","Office"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Script ausente "+t.name);foreach(var p in Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None)){var tablet=p.GetComponent<PortableTablet>();if(tablet==null||tablet.modelPrefab==null||tablet.browserPrefab==null||tablet.view==null)throw new Exception("Tablet sem configuração");var so=new SerializedObject(p);report.AppendLine("PASS "+scene+" velocidades "+so.FindProperty("moveSpeed").floatValue+" / "+so.FindProperty("sprintSpeed").floatValue+"; tablet, câmera e prefabs configurados");}}
  var roof=GameObject.Find("OfficeRoof").GetComponent<Renderer>().bounds;foreach(var floor in Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name.StartsWith("floor_tile")))if(floor.bounds.min.x<roof.min.x||floor.bounds.max.x>roof.max.x||floor.bounds.min.z<roof.min.z||floor.bounds.max.z>roof.max.z)throw new Exception("Piso descoberto "+floor.name);if(roof.min.y<3.8f)throw new Exception("Teto muito baixo");report.AppendLine("PASS cobertura de todos os pisos, collider e folga vertical: "+roof);
  var lighting=Object.FindFirstObjectByType<OfficeInteriorLighting>();if(lighting==null||lighting.fixtures.Length<8||lighting.fixtures.Any(l=>!l.enabled||l.intensity<=0))throw new Exception("Luminárias incompletas");report.AppendLine("PASS iluminação local: "+lighting.fixtures.Length+" spots ativos; ambiente global não modificado pelo controlador");
  EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");var heads=Object.FindObjectsByType<TrafficLight>(FindObjectsSortMode.None);foreach(var h in heads){var so=new SerializedObject(h);var lamps=new[]{"luzVermelha","luzAmarela","luzVerde"}.Select(f=>(GameObject)so.FindProperty(f).objectReferenceValue).ToArray();if(lamps.Any(l=>l==null||!l.GetComponent<Renderer>().enabled))throw new Exception("Lâmpada ausente "+h.name);foreach(TrafficLight.Estado state in Enum.GetValues(typeof(TrafficLight.Estado))){h.DefinirEstado(state);int i=state==TrafficLight.Estado.Vermelho?0:state==TrafficLight.Estado.Amarelo?1:2;if(lamps.Count(l=>l.activeSelf)!=1||!lamps[i].activeSelf)throw new Exception("Cor inválida "+h.name);}}
  var intersection=Object.FindFirstObjectByType<TrafficIntersection>();var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;for(int stage=0;stage<6;stage++){typeof(TrafficIntersection).GetField("etapa",flags).SetValue(intersection,stage);typeof(TrafficIntersection).GetMethod("AplicarEstado",flags).Invoke(intersection,null);foreach(var h in heads){bool horizontal=Mathf.Abs(h.transform.forward.x)>.7f;if(h.PodePassar()!=(horizontal?stage==0:stage==3))throw new Exception("Verdes conflitantes");}}report.AppendLine("PASS "+heads.Length+" sinais, três cores exclusivas e seis fases sem verdes conflitantes");report.AppendLine("RESULT SUCCESS");File.WriteAllText("v5-structure.txt",report.ToString());EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText("v5-structure.txt",report+"\nFAIL "+e);EditorApplication.Exit(1);}}
}
public sealed class GridShiftV5PlayChecks:MonoBehaviour {
 [Serializable]class State{public string text,href,value;public float x,y,dpr;public bool present;}
 StringBuilder report=new StringBuilder();List<string> errors=new List<string>();List<InputDevice> disabled=new List<InputDevice>();Keyboard keyboard;Mouse mouse;GridShiftUwbTerminal host;Camera view;string expected,reply;int id;State state;
 void Check(bool ok,string label){if(!ok)throw new Exception(label);report.AppendLine("PASS "+label);}
 void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)errors.Add(text);}
 void Current(){keyboard.MakeCurrent();mouse.MakeCurrent();}
 void Loaded(Scene scene,LoadSceneMode mode){foreach(var root in scene.GetRootGameObjects())foreach(var weather in root.GetComponentsInChildren<ClimaReal>(true))weather.enabled=false;}
 IEnumerator Start(){Application.runInBackground=true;Time.timeScale=1;Application.logMessageReceived+=Log;SceneManager.sceneLoaded+=Loaded;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;foreach(var d in InputSystem.devices.ToArray())if(d is Mouse||d is Keyboard){InputSystem.DisableDevice(d);disabled.Add(d);}keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();InputSystem.onAfterUpdate+=Current;
  var routines=new Stack<IEnumerator>();routines.Push(Run());bool success=true;while(routines.Count>0){object value=null;bool more;try{more=routines.Peek().MoveNext();if(more)value=routines.Peek().Current;}catch(Exception e){success=false;report.AppendLine("FAIL "+e);break;}if(!more){routines.Pop();continue;}if(value is IEnumerator nested&&!(value is CustomYieldInstruction)){routines.Push(nested);continue;}yield return value;}
  InputSystem.onAfterUpdate-=Current;InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);foreach(var d in disabled)if(d.added)InputSystem.EnableDevice(d);Application.logMessageReceived-=Log;SceneManager.sceneLoaded-=Loaded;success&=errors.Count==0;report.AppendLine("Erros: "+string.Join("; ",errors));report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));File.WriteAllText("v5-play.txt",report.ToString());EditorApplication.Exit(success?0:1);
 }
 IEnumerator Until(Func<bool> test,float timeout,string label){float end=Time.realtimeSinceStartup+timeout;while(!test()&&Time.realtimeSinceStartup<end)yield return null;if(!test())throw new Exception("Timeout "+label);}
 IEnumerator Tap(Key key){InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;yield return null;}
 void Bind(GridShiftUwbTerminal adapter,Camera camera){host=adapter;view=camera;host.browser.browserClient.OnTitleChange+=title=>{if(expected!=null&&title.StartsWith(expected))reply=title;};}
 IEnumerator Query(string expression){expected="GRIDSHIFT_V5_"+(++id)+"|";reply=null;host.browser.browserClient.ExecuteJs("document.title='"+expected+"'+JSON.stringify("+expression+")");yield return Until(()=>reply!=null,8,"JS");state=JsonUtility.FromJson<State>(reply.Substring(expected.Length));}
 Vector2 Point(float x,float y){var rect=host.browser.GetComponent<RectTransform>();var b=rect.rect;var texture=host.browser.browserClient.BrowserTexture;return view.WorldToScreenPoint(rect.TransformPoint(new Vector3(b.xMin+x/texture.width*b.width,b.yMax-y/texture.height*b.height)));}
 IEnumerator Click(Vector2 point){InputSystem.QueueStateEvent(mouse,new MouseState{position=point});yield return null;yield return null;InputSystem.QueueStateEvent(mouse,new MouseState{position=point,buttons=1});yield return null;yield return null;InputSystem.QueueStateEvent(mouse,new MouseState{position=point});yield return null;yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Content(){yield return Until(()=>host.inputRouter.Ready&&host.inputRouter.Focused,45,"CEF pronto");yield return new WaitForSecondsRealtime(1);float end=Time.realtimeSinceStartup+60;do{yield return Query("({text:(document.body?document.body.innerText:String()),href:location.href,dpr:devicePixelRatio,x:innerWidth,y:innerHeight})");if(state.text.Contains("UrbanLink")||state.text.Contains("cidade"))break;yield return new WaitForSecondsRealtime(1);}while(Time.realtimeSinceStartup<end);Check(state.text.Contains("UrbanLink")||state.text.Contains("cidade"),"UrbanLink real carregado; "+state.href);float zoomEnd=Time.realtimeSinceStartup+8;do{yield return Query("({dpr:devicePixelRatio,x:innerWidth,y:innerHeight,href:location.href,value:getComputedStyle(document.documentElement).zoom})");if(Mathf.Abs(state.dpr-1.5f)<.02f)break;yield return new WaitForSecondsRealtime(.3f);}while(Time.realtimeSinceStartup<zoomEnd);Check(Mathf.Abs(state.dpr-1.5f)<.02f&&Mathf.Abs(float.Parse(state.value,System.Globalization.CultureInfo.InvariantCulture)-1)<.02f,"zoom nativo 150% confirmado por DPR e viewport, sem CSS adicional");report.AppendLine("INFO textura "+host.ActualResolution+"; viewport CSS "+state.x+"x"+state.y+"; DPR "+state.dpr);}
 IEnumerator History(){
  var nav=host.navigation;
  yield return Query("(()=>{history.pushState({},'',location.pathname+'#gridshift-a');history.pushState({},'',location.pathname+'#gridshift-b');return {href:location.href}})()");
  yield return new WaitForSecondsRealtime(.5f);yield return Until(()=>nav.CanGoBack,8,"estado histórico real");nav.Back();
  float end=Time.realtimeSinceStartup+8;do{yield return new WaitForSecondsRealtime(.25f);yield return Query("({href:location.href})");if(state.href.EndsWith("#gridshift-a"))break;}while(Time.realtimeSinceStartup<end);
  report.AppendLine("INFO back href="+state.href);Check(state.href.EndsWith("#gridshift-a"),"Voltar usa histórico Chromium");
  yield return Until(()=>nav.CanGoForward,8,"Avançar habilitado");nav.Forward();
  end=Time.realtimeSinceStartup+8;do{yield return new WaitForSecondsRealtime(.25f);yield return Query("({href:location.href})");if(state.href.EndsWith("#gridshift-b"))break;}while(Time.realtimeSinceStartup<end);
  Check(state.href.EndsWith("#gridshift-b"),"Avançar usa histórico Chromium");bool loaded=false;VoltstroStudios.UnityWebBrowser.Events.OnLoadFinishDelegate callback=url=>loaded=true;host.browser.browserClient.OnLoadFinish+=callback;nav.Reload();yield return Until(()=>loaded,30,"recarregar");host.browser.browserClient.OnLoadFinish-=callback;Check(loaded,"Recarregar conclui navegação nativa");nav.Home();yield return Content();Check(!state.href.Contains("#gridshift"),"Home retorna ao UrbanLink preservando instância");
 }
 bool Painted(){if(host==null||!host.inputRouter.Ready)return false;var texture=host.browser.browserClient.BrowserTexture;int bright=0;for(int x=1;x<9;x++)for(int y=1;y<9;y++){var color=texture.GetPixel(texture.width*x/10,texture.height*y/10);if(Mathf.Max(color.r,color.g,color.b)>.6f)bright++;}return bright>3;}
 IEnumerator Shot(string name,Camera camera=null){yield return new WaitForSecondsRealtime(1.5f);if(name.StartsWith("tablet")||name.StartsWith("computador")||name.StartsWith("pc-debug")){yield return Until(Painted,10,"pixels reais do Chromium "+name);Check(Painted(),"textura renderizada não está preta: "+name);}if(camera==null)camera=view;Directory.CreateDirectory("v5-images");var go=new GameObject("V5Capture");var copy=go.AddComponent<Camera>();copy.CopyFrom(camera);copy.enabled=false;copy.transform.SetPositionAndRotation(camera.transform.position,camera.transform.rotation);var rt=new RenderTexture(1920,1080,24);copy.targetTexture=rt;Canvas.ForceUpdateCanvases();copy.Render();if(host!=null&&host.inputRouter.Ready){File.WriteAllBytes("v5-images/"+name+"-web.png",host.browser.browserClient.BrowserTexture.EncodeToPNG());var image=host.browser.GetComponent<RawImage>();report.AppendLine("INFO "+name+" image enabled="+image.enabled+" cull="+image.canvasRenderer.cull+" alpha="+image.canvasRenderer.GetInheritedAlpha());}var active=RenderTexture.active;RenderTexture.active=rt;var picture=new Texture2D(1920,1080,TextureFormat.RGB24,false);picture.ReadPixels(new Rect(0,0,1920,1080),0,0);picture.Apply();File.WriteAllBytes("v5-images/"+name+".png",picture.EncodeToPNG());RenderTexture.active=active;rt.Release();Destroy(rt);Destroy(picture);Destroy(go);yield return null;}
 IEnumerator WebInput(){
  yield return Query("(()=>{let e=document.createElement('input');e.id='gridshift-test-input';e.style='position:fixed;left:20px;top:140px;width:300px;height:60px;z-index:2147483647';document.body.appendChild(e);let r=e.getBoundingClientRect();return {x:(r.x+r.width/2)*devicePixelRatio,y:(r.y+r.height/2)*devicePixelRatio}})()");
  yield return Click(Point(state.x,state.y));foreach(char c in "GridShift ação42"){InputSystem.QueueTextEvent(keyboard,c);yield return null;}yield return new WaitForSecondsRealtime(.4f);yield return Query("({value:document.getElementById('gridshift-test-input').value})");Check(state.value=="GridShift ação42","mouse e digitação real a 150% no dispositivo ativo");yield return Tap(Key.Backspace);yield return new WaitForSecondsRealtime(.3f);yield return Query("({value:document.getElementById('gridshift-test-input').value})");Check(state.value=="GridShift ação4","Backspace no navegador ativo; valor="+state.value);host.browser.browserClient.ExecuteJs("document.getElementById('gridshift-test-input').remove()");yield return null;
 }
 IEnumerator Tablet(PortableTablet tablet,bool useEscape,string name){var p=tablet.player;var camera=tablet.view;var local=camera.transform.localPosition;var rotation=camera.transform.localRotation;float fov=camera.fieldOfView;yield return Tap(Key.G);Check(tablet.IsOpen,"G abre tablet em "+name);var model=camera.transform.Find("PortableTabletViewModel");float start=model.localPosition.y;yield return Until(()=>!tablet.Animating,5,"animação subir");Check(model.localPosition.y>start+.1f,"tablet 3D sobe suavemente em "+name);Bind(tablet.Browser,camera);yield return Content();Check(p.ControlsBlocked,"tablet bloqueia movimento e rotação");yield return Shot("tablet-"+name);yield return History();yield return WebInput();yield return Shot("tablet-final-"+name);var before=p.transform.position;InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W,Key.LeftShift,Key.Space,Key.E));yield return new WaitForSecondsRealtime(.3f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());Check(Vector3.Distance(before,p.transform.position)<.002f,"teclas da página não movimentam avatar "+name);yield return Tap(useEscape?Key.Escape:Key.G);yield return Until(()=>!tablet.IsOpen,5,"guardar tablet");Check(!p.ControlsBlocked&&!PauseMenu.Instance.IsOpen&&!host.inputRouter.Focused,"tablet restaura controles e não abre pausa "+name);Check(Vector3.Distance(local,camera.transform.localPosition)<.001f&&Quaternion.Angle(rotation,camera.transform.localRotation)<.01f&&Mathf.Abs(fov-camera.fieldOfView)<.01f,"tablet preserva posição, rotação e FOV "+name);}
 IEnumerator Run(){yield return new WaitForSecondsRealtime(3);if(SceneManager.GetActiveScene().name=="Office"){var debugTerminal=Object.FindFirstObjectByType<ComputerInteraction>();debugTerminal.EnterComputer();yield return Until(()=>!debugTerminal.MovingCamera,5,"zoom PC");Bind((GridShiftUwbTerminal)debugTerminal.webView,debugTerminal.playerCamera);yield return Content();yield return Shot("pc-debug");debugTerminal.ExitComputer();yield return Until(()=>!debugTerminal.MovingCamera,5,"retorno");yield return Tablet(debugTerminal.playerMovement.GetComponent<PortableTablet>(),true,"office-debug");yield break;}var city=WorldSession.Instance;var p=Object.FindFirstObjectByType<PlayerMovement>();var traffic=Object.FindFirstObjectByType<TrafficManager>();int managerID=traffic.GetInstanceID();float clock=city.ClockTime;var tablet=p.GetComponent<PortableTablet>();yield return Tablet(tablet,false,"cidade");Check(city.ClockTime>clock+1,"relógio e cidade continuam durante tablet");
  var cityBrowser=tablet.Browser;city.RequestTransition("Office",p.transform);yield return Until(()=>!city.Busy,35,"entrada Office");Check(!tablet.gameObject.activeInHierarchy,"avatar cidade suspenso na Office");Check(!Object.FindObjectsByType<GridShiftUwbTerminal>(FindObjectsSortMode.None).Any(a=>a.name=="PortableChromium"),"navegador portátil descarregado ao trocar de cena");
  var terminal=Object.FindObjectsByType<ComputerInteraction>(FindObjectsSortMode.None).First(t=>t.gameObject.scene.name=="Office");p=terminal.playerMovement;tablet=p.GetComponent<PortableTablet>();var lighting=Object.FindFirstObjectByType<OfficeInteriorLighting>();var intensities=lighting.fixtures.Select(l=>l.intensity).ToArray();
  foreach(float hour in new[]{12f,23f}){typeof(WorldSession).GetField("clockTime",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(city,hour/24f*1920);yield return new WaitForSecondsRealtime(.5f);Check(lighting.fixtures.Select((l,i)=>l.enabled&&Mathf.Abs(l.intensity-intensities[i])<.001f).All(b=>b),"luzes Office permanentes às "+hour+"h");view=p.CameraTransform.GetComponent<Camera>();yield return Shot("office-"+hour);var probe=new GameObject("InteriorProbe").AddComponent<Camera>();probe.enabled=false;probe.CopyFrom(view);probe.enabled=false;probe.transform.position=lighting.transform.position+new Vector3(6,1.7f,3);probe.transform.LookAt(lighting.transform.position+new Vector3(-5,2,-8));yield return Shot("office-interior-"+hour,probe);Destroy(probe.gameObject);}
  var pc=terminal.webView as GridShiftUwbTerminal;terminal.EnterComputer();yield return Until(()=>!terminal.MovingCamera,5,"zoom PC");Bind(pc,terminal.playerCamera);yield return Content();yield return WebInput();yield return Shot("computador-150");yield return Tap(Key.G);Check(!tablet.IsOpen&&terminal.UsingComputer,"PC bloqueia tablet simultâneo");yield return History();yield return Tap(Key.Escape);yield return Until(()=>!terminal.MovingCamera,5,"retorno PC");Check(!terminal.UsingComputer&&!PauseMenu.Instance.IsOpen&&!p.ControlsBlocked,"ESC retorna do PC sem pausa");
  yield return Tablet(tablet,true,"office");Check(Object.FindObjectsByType<GridShiftUwbTerminal>(FindObjectsSortMode.None).Count(a=>a.inputRouter!=null&&a.inputRouter.Ready)==1,"PC e tablet Office compartilham um único Chromium");terminal.EnterComputer();yield return Until(()=>!terminal.MovingCamera&&pc.inputRouter.Focused,8,"PC após tablet");Check(pc.browser.transform.IsChildOf(terminal.screenContent.transform),"navegador retorna ao monitor físico após tablet");terminal.ExitComputer();yield return Until(()=>!terminal.MovingCamera,5,"saída PC repetida");
  city.RequestTransition("SampleScene",p.transform);yield return Until(()=>!city.Busy,35,"retorno cidade");Check(traffic!=null&&traffic.GetInstanceID()==managerID,"simulação de trânsito preservada na viagem Office");p=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(t=>t.gameObject.scene.name=="SampleScene");tablet=p.GetComponent<PortableTablet>();yield return Tablet(tablet,true,"cidade-retorno");Check(Object.FindObjectsByType<PortableTablet>(FindObjectsSortMode.None).Length==1,"sem tablets duplicados após transição");
 }
